// 原地雜湊：把數字 x 放到索引 x-1 的位置
// 時間複雜度: O(n)，空間複雜度: O(1)
function firstMissingPositive(nums) {
    const n = nums.length;
    for (let i = 0; i < n; i++) {
        // 只要 nums[i] 在 1..n 且還沒歸位，就交換到正確位置
        while (nums[i] >= 1 && nums[i] <= n && nums[nums[i] - 1] !== nums[i]) {
            const j = nums[i] - 1;
            [nums[i], nums[j]] = [nums[j], nums[i]];
        }
    }
    for (let i = 0; i < n; i++) {
        if (nums[i] !== i + 1)
            return i + 1;
    }
    return n + 1;
}

