#include <vector>

class Solution {
public:
    /**
     * 方法：原地哈希
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    int firstMissingPositive(vector<int>& nums) {
        int n = nums.size();

        // 步驟 1: 將每個數字放到正確位置
        for (int i = 0; i < n; i++) {
            // 持續交換直到當前位置無法交換
            while (nums[i] >= 1 && nums[i] <= n && 
                   nums[nums[i] - 1] != nums[i]) {
                // 將 nums[i] 放到索引 nums[i]-1
                int correct_idx = nums[i] - 1;
                swap(nums[i], nums[correct_idx]);
            }
        }

        // 步驟 2: 找第一個不匹配的位置
        for (int i = 0; i < n; i++) {
            if (nums[i] != i + 1) {
                return i + 1;
            }
        }

        // 所有位置都匹配，答案是 n+1
        return n + 1;
    }
};

